CREATE TABLE IF NOT EXISTS space_ai_agents (id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, provider text NOT NULL, model text, instructions text, visibility text NOT NULL DEFAULT 'private', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS space_connections (id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, kind text NOT NULL, endpoint text, credential_ref text, billing text NOT NULL DEFAULT 'external', status text NOT NULL DEFAULT 'connected', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS space_compute_profiles (id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, kind text NOT NULL, endpoint text, provider text, billing text NOT NULL DEFAULT 'none', status text NOT NULL DEFAULT 'online', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_space_ai_agents_space ON space_ai_agents(space_id); CREATE INDEX IF NOT EXISTS idx_space_connections_space ON space_connections(space_id); CREATE INDEX IF NOT EXISTS idx_space_compute_profiles_space ON space_compute_profiles(space_id);
